from pathlib import Path
import json,pickle,copy,base64,hashlib
B=Path('/home/junhao/quan/parallel_test_solver/CCMKCP');H=B/'work/r01_budget_robust_20261126';assert Path.cwd()==B
code=base64.b64decode('');scope={};exec(code,scope);verify=scope['verify_budget'];checks=0
for fixture,capacity in [('LAB_3_2_500_',.5),('LAB_2_2_500_',1.25)]:
 raw=json.loads((H/'integration60'/fixture/'S10_search.json').read_text());F=H/'fixtures'/fixture
 groups=pickle.loads((F/'node_to_factor.pkl').read_bytes());groups=[groups[k] for k in sorted(groups)] if isinstance(groups,dict) else groups
 costs=[float(x) for x in (F/'cost.txt').read_text().split()];samples=[(F/(str(j)+'_sample.txt')).read_text().split() for j in range(len(costs))]
 v=verify(raw,groups,costs,samples,capacity);checks+=1
 for path,value in [(('budget_RO_model','probability_coverage_claim'),True),(('budget_RO_model','positive_budget_only'),False),(('budget_RO_model','historical_solution_inputs'),True),(('budget_RO_model','budget_order'),['0']),(('budget_RO_statistics','unique_proposals'),9999),(('budget_RO_statistics','no_LSS_calls_in_generator'),False)]:
  bad=copy.deepcopy(raw);bad[path[0]][path[1]]=value
  try:verify(bad,groups,costs,samples,capacity)
  except AssertionError:checks+=1
  else:raise AssertionError('Accepted tampered metadata '+str(path))
 for field,value in [('gamma','0'),('budget_worst_sum','999999'),('own_run_raw_samples',False),('not_a_probability_estimate',False),('robust_slack','999999')]:
  bad=copy.deepcopy(raw);bad['budget_RO_proposals'][0][field]=value
  try:verify(bad,groups,costs,samples,capacity)
  except AssertionError:checks+=1
  else:raise AssertionError('Accepted tampered proposal '+field)
result={'status':'PASS','checks':checks,'reader_sha256':hashlib.sha256(code).hexdigest(),'no_solver_or_sampler_import':True};(H/'BUDGET_READER_TEST.json').write_text(json.dumps(result,indent=2));print(json.dumps(result))
